import java.util.*;
import java.util.function.*;

public class ShapeStudioPatterns {
    // Singleton (holder idiom): the JVM creates INSTANCE lazily and thread-safely on first get()
    static final class Config {
        final String units = "cm";
        private Config() {}
        private static class Holder { static final Config INSTANCE = new Config(); }
        static Config get() { return Holder.INSTANCE; }
    }

    interface Shape { String name(); double size(); double area(); }
    record Circle(double size) implements Shape {
        public String name() { return "circle"; }
        public double area() { return Math.PI * size * size; }
    }
    record Square(double size) implements Shape {
        public String name() { return "square"; }
        public double area() { return size * size; }
    }
    record Triangle(double size) implements Shape { // equilateral
        public String name() { return "triangle"; }
        public double area() { return Math.sqrt(3) / 4 * size * size; }
    }
    record Hexagon(double size) implements Shape { // regular
        public String name() { return "hexagon"; }
        public double area() { return 3 * Math.sqrt(3) / 2 * size * size; }
    }

    // Factory: callers ask for a shape by name and never see the concrete class
    static final class ShapeFactory {
        private final Map<String, DoubleFunction<Shape>> registry = new TreeMap<>();
        void register(String name, DoubleFunction<Shape> maker) { registry.put(name, maker); }
        Set<String> names() { return registry.keySet(); }
        Shape create(String name, double size) {
            DoubleFunction<Shape> maker = registry.get(name);
            if (maker == null) throw new IllegalArgumentException("unknown shape '" + name + "'");
            return maker.apply(size);
        }
    }

    // Observer subject: notifies every listener, without knowing what they do
    static final class Drawing {
        final List<Shape> shapes = new ArrayList<>();
        private final List<Consumer<Shape>> listeners = new ArrayList<>();
        void subscribe(Consumer<Shape> listener) { listeners.add(listener); }
        void add(Shape shape) {
            shapes.add(shape);
            listeners.forEach(listener -> listener.accept(shape));
        }
    }

    static String fmt(double x) { return String.format("%.2f", x); }

    // Strategy: the comparator decides the order; this code never changes
    static void printSorted(String label, List<Shape> shapes, Comparator<Shape> order) {
        List<String> parts = shapes.stream().sorted(order).map(s -> s.name() + " " + fmt(s.area())).toList();
        System.out.println("sorted by " + label + ": " + String.join(", ", parts));
    }

    public static void main(String[] args) {
        Config config = Config.get();
        System.out.println("same Config instance: " + (Config.get() == config) + " (units=" + config.units + ")");

        ShapeFactory factory = new ShapeFactory();
        factory.register("circle", Circle::new);
        factory.register("square", Square::new);
        factory.register("triangle", Triangle::new);

        Drawing drawing = new Drawing();
        drawing.subscribe(s -> System.out.println("[log] added " + s.name() + " " + fmt(s.size()) + " "
                + config.units + " -> area " + fmt(s.area())));
        drawing.subscribe(s -> {
            double total = drawing.shapes.stream().mapToDouble(Shape::area).sum();
            System.out.println("[stats] shapes=" + drawing.shapes.size() + " total area=" + fmt(total));
        });

        drawing.add(factory.create("circle", 1.0));
        drawing.add(factory.create("square", 2.0));
        drawing.add(factory.create("triangle", 3.0));

        try {
            factory.create("hexagon", 1.0);
        } catch (IllegalArgumentException e) {
            System.out.println("error: " + e.getMessage());
        }

        factory.register("hexagon", Hexagon::new); // open/closed: a new type is one register() call
        System.out.println("known shapes: " + String.join(", ", factory.names()));
        drawing.add(factory.create("hexagon", 1.0));

        printSorted("area", drawing.shapes, Comparator.comparingDouble(Shape::area));
        printSorted("name", drawing.shapes, Comparator.comparing(Shape::name));
    }
}

