#include <algorithm>
#include <cmath>
#include <cstdio>
#include <functional>
#include <map>
#include <memory>
#include <stdexcept>
#include <string>
#include <vector>

// Singleton (Meyers): a function-local static is created once, thread-safely, on first call
class Config {
public:
    static Config& get() {
        static Config instance;
        return instance;
    }
    const std::string units = "cm";
    Config(const Config&) = delete;            // no copies of the one instance
    Config& operator=(const Config&) = delete;
private:
    Config() = default;
};

struct Shape {
    std::string name;
    double size;
    Shape(std::string n, double s) : name(std::move(n)), size(s) {}
    virtual ~Shape() = default;
    virtual double area() const = 0;
};
struct Circle : Shape {
    explicit Circle(double s) : Shape("circle", s) {}
    double area() const override { return M_PI * size * size; }
};
struct Square : Shape {
    explicit Square(double s) : Shape("square", s) {}
    double area() const override { return size * size; }
};
struct Triangle : Shape {  // equilateral
    explicit Triangle(double s) : Shape("triangle", s) {}
    double area() const override { return std::sqrt(3.0) / 4 * size * size; }
};
struct Hexagon : Shape {  // regular
    explicit Hexagon(double s) : Shape("hexagon", s) {}
    double area() const override { return 3 * std::sqrt(3.0) / 2 * size * size; }
};

using ShapePtr = std::shared_ptr<Shape>;

// Factory: callers ask for a shape by name and never see the concrete class
class ShapeFactory {
    std::map<std::string, std::function<ShapePtr(double)>> registry;  // std::map keeps names sorted
public:
    template <typename T> void add() {
        registry[T(1).name] = [](double s) { return std::make_shared<T>(s); };
    }
    std::string names() const {
        std::string out;
        for (const auto& [name, maker] : registry) out += (out.empty() ? "" : ", ") + name;
        return out;
    }
    ShapePtr create(const std::string& name, double size) const {
        auto it = registry.find(name);
        if (it == registry.end()) throw std::invalid_argument("unknown shape '" + name + "'");
        return it->second(size);
    }
};

// Observer subject: notifies every listener, without knowing what they do
struct Drawing {
    std::vector<ShapePtr> shapes;
    std::vector<std::function<void(const Shape&)>> listeners;
    void subscribe(std::function<void(const Shape&)> l) { listeners.push_back(std::move(l)); }
    void add(ShapePtr s) {
        shapes.push_back(s);
        for (auto& listener : listeners) listener(*s);
    }
};

// Strategy: the comparator decides the order; this code never changes
void printSorted(const std::string& label, std::vector<ShapePtr> shapes,
                 const std::function<bool(const ShapePtr&, const ShapePtr&)>& less) {
    std::sort(shapes.begin(), shapes.end(), less);
    std::printf("sorted by %s: ", label.c_str());
    for (size_t i = 0; i < shapes.size(); ++i)
        std::printf("%s%s %.2f", i ? ", " : "", shapes[i]->name.c_str(), shapes[i]->area());
    std::printf("\n");
}

int main() {
    Config& config = Config::get();
    std::printf("same Config instance: %s (units=%s)\n", &Config::get() == &config ? "true" : "false",
                config.units.c_str());

    ShapeFactory factory;
    factory.add<Circle>();
    factory.add<Square>();
    factory.add<Triangle>();

    Drawing drawing;
    drawing.subscribe([&](const Shape& s) {
        std::printf("[log] added %s %.2f %s -> area %.2f\n", s.name.c_str(), s.size, config.units.c_str(), s.area());
    });
    drawing.subscribe([&](const Shape&) {
        double total = 0;
        for (const auto& x : drawing.shapes) total += x->area();
        std::printf("[stats] shapes=%zu total area=%.2f\n", drawing.shapes.size(), total);
    });

    drawing.add(factory.create("circle", 1.0));
    drawing.add(factory.create("square", 2.0));
    drawing.add(factory.create("triangle", 3.0));

    try {
        factory.create("hexagon", 1.0);
    } catch (const std::invalid_argument& e) {
        std::printf("error: %s\n", e.what());
    }

    factory.add<Hexagon>();  // open/closed: a new type is one registration call
    std::printf("known shapes: %s\n", factory.names().c_str());
    drawing.add(factory.create("hexagon", 1.0));

    printSorted("area", drawing.shapes, [](const ShapePtr& a, const ShapePtr& b) { return a->area() < b->area(); });
    printSorted("name", drawing.shapes, [](const ShapePtr& a, const ShapePtr& b) { return a->name < b->name; });
}

