from typing import Callable


class Config:
    """Singleton: one shared settings object for the whole program."""
    _instance = None

    def __init__(self):
        self.units = "cm"

    @classmethod
    def get(cls):
        if cls._instance is None:  # created lazily, on first use
            cls._instance = cls()
        return cls._instance


class Shape:
    name = "shape"

    def __init__(self, size: float):
        self.size = size


class Circle(Shape):
    name = "circle"
    def area(self): return math.pi * self.size ** 2


class Square(Shape):
    name = "square"
    def area(self): return self.size ** 2


class Triangle(Shape):  # equilateral
    name = "triangle"
    def area(self): return math.sqrt(3) / 4 * self.size ** 2


class Hexagon(Shape):  # regular
    name = "hexagon"
    def area(self): return 3 * math.sqrt(3) / 2 * self.size ** 2


class ShapeFactory:
    """Factory: callers ask for a shape by name and never see the concrete class."""
    def __init__(self):
        self._registry: dict[str, Callable[[float], Shape]] = {}

    def register(self, name, maker):
        self._registry[name] = maker

    def names(self):
        return sorted(self._registry)

    def create(self, name, size):
        if name not in self._registry:
            raise ValueError(f"unknown shape '{name}'")
        return self._registry[name](size)


class Drawing:
    """Observer subject: notifies every listener, without knowing what they do."""
    def __init__(self):
        self.shapes: list[Shape] = []
        self._listeners: list[Callable[[Shape], None]] = []

    def subscribe(self, listener):
        self._listeners.append(listener)

    def add(self, shape):
        self.shapes.append(shape)
        for listener in self._listeners:
            listener(shape)


def print_sorted(label, shapes, key):
    # Strategy: the key function decides the order; this code never changes
    parts = [f"{s.name} {s.area():.2f}" for s in sorted(shapes, key=key)]
    print(f"sorted by {label}: {', '.join(parts)}")


