import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;

public class SingletonHolderDemo {
    static final class Settings {
        static final AtomicInteger CREATED = new AtomicInteger(); // counts constructor runs
        private volatile String theme = "dark";

        private Settings() { // private: nobody else can call new Settings()
            CREATED.incrementAndGet();
            System.out.println("  Settings() running: loading settings once");
        }

        // Holder idiom: Holder is initialized on the first get(), and the JVM makes class
        // initialization thread-safe, so no synchronized and no volatile instance field are needed.
        private static final class Holder {
            static final Settings INSTANCE = new Settings();
        }

        static Settings get() { return Holder.INSTANCE; }
        String theme() { return theme; }
        void setTheme(String t) { theme = t; }
    }
    // Simplest alternative: enum Settings { INSTANCE; } (also safe against serialization and reflection).
    // A "static synchronized getInstance()" also works but takes a lock on every single call.

    public static void main(String[] args) throws InterruptedException {
        System.out.println("instances created before first get(): " + Settings.CREATED.get());

        Settings[] results = new Settings[4];
        List<Thread> threads = new ArrayList<>();
        for (int i = 0; i < 4; i++) {
            final int slot = i;
            threads.add(new Thread(() -> results[slot] = Settings.get()));
        }
        for (Thread t : threads) t.start();
        for (Thread t : threads) t.join(); // wait for every thread before printing

        Set<Settings> distinct = Collections.newSetFromMap(new IdentityHashMap<>());
        distinct.addAll(Arrays.asList(results));
        System.out.println("4 threads called get(); distinct instances seen: " + distinct.size());
        System.out.println("instances created: " + Settings.CREATED.get());

        // Every caller shares the same object, so its state is effectively global
        System.out.println("caller 1 reads theme: " + Settings.get().theme());
        Settings.get().setTheme("light");
        System.out.println("caller 2 sets theme: light");
        System.out.println("caller 3 reads theme: " + Settings.get().theme());
    }
}

