#include <cstdio>
#include <set>
#include <string>
#include <thread>
#include <vector>

class Settings {
public:
    static inline std::atomic<int> created{0};  // counts constructor runs

    // Meyers singleton: since C++11 a function-local static is initialized exactly once,
    // even when several threads call get() at the same time.
    static Settings& get() {
        static Settings instance;
        return instance;
    }
    Settings(const Settings&) = delete;  // forbid copies of the one instance
    Settings& operator=(const Settings&) = delete;

    std::string theme = "dark";

private:
    Settings() {  // private: nobody else can construct one
        ++created;
        std::printf("  Settings() running: loading settings once\n");
    }
};

int main() {
    std::printf("instances created before first get(): %d\n", Settings::created.load());

    std::vector<Settings*> results(4);
    std::vector<std::thread> threads;
    for (int i = 0; i < 4; ++i) threads.emplace_back([&results, i] { results[i] = &Settings::get(); });
    for (auto& t : threads) t.join();  // wait for every thread before printing

    std::set<Settings*> distinct(results.begin(), results.end());
    std::printf("4 threads called get(); distinct instances seen: %zu\n", distinct.size());
    std::printf("instances created: %d\n", Settings::created.load());

    // Every caller shares the same object, so its state is effectively global
    std::printf("caller 1 reads theme: %s\n", Settings::get().theme.c_str());
    Settings::get().theme = "light";
    std::printf("caller 2 sets theme: light\n");
    std::printf("caller 3 reads theme: %s\n", Settings::get().theme.c_str());
}

