import java.util.*;
import java.util.function.Supplier;

public class NotifierFactoryDemo {
    // Callers only ever see this interface, never the concrete classes
    interface Notifier { String send(String message); }
    static class EmailNotifier implements Notifier { public String send(String m) { return "[EMAIL] " + m; } }
    static class SmsNotifier implements Notifier { public String send(String m) { return "[SMS] " + m; } }
    static class PushNotifier implements Notifier { public String send(String m) { return "[PUSH] " + m; } }

    // Version 1: a switch. Every new type means editing this method (violates open/closed).
    static Notifier createWithSwitch(String type) {
        return switch (type) {
            case "email" -> new EmailNotifier();
            case "sms" -> new SmsNotifier();
            default -> throw new IllegalArgumentException("unknown type '" + type + "'");
        };
    }

    // Version 2: a registry of Suppliers. New types are registered, the factory is never edited.
    static class NotifierRegistry {
        private final Map<String, Supplier<Notifier>> makers = new TreeMap<>(); // sorted names
        void register(String type, Supplier<Notifier> maker) { makers.put(type, maker); }
        Set<String> types() { return makers.keySet(); }
        Notifier create(String type) {
            Supplier<Notifier> maker = makers.get(type);
            if (maker == null) throw new IllegalArgumentException("no notifier registered for '" + type + "'");
            return maker.get(); // a brand-new object on every call
        }
    }

    static void tryCreate(NotifierRegistry registry, String type) {
        try {
            System.out.println("registry: " + type + " -> " + registry.create(type).send("Grades posted"));
        } catch (IllegalArgumentException e) {
            System.out.println("registry: " + type + " -> error: " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        for (String type : List.of("email", "sms")) {
            System.out.println("switch factory: " + type + " -> " + createWithSwitch(type).send("Grades posted"));
        }

        NotifierRegistry registry = new NotifierRegistry();
        registry.register("email", EmailNotifier::new);
        registry.register("sms", SmsNotifier::new);
        System.out.println("registry knows: " + String.join(", ", registry.types()));
        tryCreate(registry, "email");
        tryCreate(registry, "push");

        registry.register("push", PushNotifier::new); // plug in a new type; no existing code changes
        System.out.println("registry knows: " + String.join(", ", registry.types()));
        tryCreate(registry, "push");
        System.out.println("two creates give different objects: " + (registry.create("sms") != registry.create("sms")));
    }
}

