#include <cstdio>
#include <functional>
#include <map>
#include <memory>
#include <stdexcept>
#include <string>

// Callers only ever see this interface, never the concrete classes
struct Notifier {
    virtual ~Notifier() = default;
    virtual std::string send(const std::string& m) const = 0;
};
struct EmailNotifier : Notifier { std::string send(const std::string& m) const override { return "[EMAIL] " + m; } };
struct SmsNotifier : Notifier { std::string send(const std::string& m) const override { return "[SMS] " + m; } };
struct PushNotifier : Notifier { std::string send(const std::string& m) const override { return "[PUSH] " + m; } };

// Version 1: every new type means editing this function (violates open/closed)
std::unique_ptr<Notifier> createWithSwitch(const std::string& type) {
    if (type == "email") return std::make_unique<EmailNotifier>();
    if (type == "sms") return std::make_unique<SmsNotifier>();
    throw std::invalid_argument("unknown type '" + type + "'");
}

// Version 2: new types are registered; the factory itself is never edited
class NotifierRegistry {
    std::map<std::string, std::function<std::unique_ptr<Notifier>()>> makers;  // sorted by name
public:
    template <typename T> void add(const std::string& type) {
        makers[type] = [] { return std::make_unique<T>(); };
    }
    std::string types() const {
        std::string out;
        for (const auto& [type, maker] : makers) out += (out.empty() ? "" : ", ") + type;
        return out;
    }
    std::unique_ptr<Notifier> create(const std::string& type) const {
        auto it = makers.find(type);
        if (it == makers.end()) throw std::invalid_argument("no notifier registered for '" + type + "'");
        return it->second();  // a brand-new object on every call
    }
};

void tryCreate(const NotifierRegistry& registry, const std::string& type) {
    try {
        std::printf("registry: %s -> %s\n", type.c_str(), registry.create(type)->send("Grades posted").c_str());
    } catch (const std::invalid_argument& e) {
        std::printf("registry: %s -> error: %s\n", type.c_str(), e.what());
    }
}

int main() {
    for (const std::string type : {"email", "sms"})
        std::printf("switch factory: %s -> %s\n", type.c_str(), createWithSwitch(type)->send("Grades posted").c_str());

    NotifierRegistry registry;
    registry.add<EmailNotifier>("email");
    registry.add<SmsNotifier>("sms");
    std::printf("registry knows: %s\n", registry.types().c_str());
    tryCreate(registry, "email");
    tryCreate(registry, "push");

    registry.add<PushNotifier>("push");  // plug in a new type; no existing code changes
    std::printf("registry knows: %s\n", registry.types().c_str());
    tryCreate(registry, "push");
    auto a = registry.create("sms"), b = registry.create("sms");
