public class SensorObserverDemo {
    // The listener interface: the sensor depends on this, not on Display or Alarm
    interface TemperatureListener { void onReading(double celsius); }

    static class Display implements TemperatureListener {
        public void onReading(double c) { System.out.printf("  display: %.1f C%n", c); }
    }

    static class Alarm implements TemperatureListener {
        private final double limit;
        Alarm(double limit) { this.limit = limit; }
        public void onReading(double c) {
            if (c > limit) System.out.printf("  alarm: %.1f C is above %.1f C!%n", c, limit);
        }
    }

    // The subject: keeps a list of listeners and calls each one when its state changes
    static class Sensor {
        private final List<TemperatureListener> listeners = new ArrayList<>();
        int notifications = 0;
        void subscribe(TemperatureListener l) { listeners.add(l); }
        void unsubscribe(TemperatureListener l) { listeners.remove(l); }
        void setReading(double celsius) {
            System.out.printf("reading %.1f C%n", celsius);
            for (TemperatureListener l : List.copyOf(listeners)) { // copy: a listener may unsubscribe itself
                l.onReading(celsius);
                notifications++;
            }
        }
    }

    public static void main(String[] args) {
        Sensor sensor = new Sensor();
        Display display = new Display();
        sensor.subscribe(display);
        sensor.subscribe(new Alarm(30.0));

