        sensor.setReading(31.5);
        System.out.println("unsubscribe display");
        sensor.unsubscribe(display); // forgetting this is the classic Observer memory leak
        sensor.setReading(33.0);
        // A lambda is a listener too, because TemperatureListener has a single method
        sensor.subscribe(c -> System.out.printf("  logger: saved %.1f%n", c));
        sensor.setReading(29.5);
        System.out.println("notifications sent: " + sensor.notifications);
    }
}

