// The listener interface: the sensor depends on this, not on Display or Alarm
struct TemperatureListener {
    virtual ~TemperatureListener() = default;
    virtual void onReading(double celsius) = 0;
};

struct Display : TemperatureListener {
    void onReading(double c) override { std::printf("  display: %.1f C\n", c); }
};

struct Alarm : TemperatureListener {
    double limit;
    explicit Alarm(double l) : limit(l) {}
    void onReading(double c) override {
        if (c > limit) std::printf("  alarm: %.1f C is above %.1f C!\n", c, limit);
    }
};

struct Logger : TemperatureListener {
    void onReading(double c) override { std::printf("  logger: saved %.1f\n", c); }
};

// The subject: keeps a list of listeners and calls each one when its state changes.
// It stores non-owning pointers, so listeners must outlive their subscription.
class Sensor {
    std::vector<TemperatureListener*> listeners;
public:
    int notifications = 0;
    void subscribe(TemperatureListener* l) { listeners.push_back(l); }
    void unsubscribe(TemperatureListener* l) { listeners.erase(std::remove(listeners.begin(), listeners.end(), l), listeners.end()); }
    void setReading(double celsius) {
        std::printf("reading %.1f C\n", celsius);
        auto snapshot = listeners;  // copy: a listener may unsubscribe itself
        for (auto* l : snapshot) {
            l->onReading(celsius);
            ++notifications;
        }
    }
};

int main() {
    Sensor sensor;
    Display display;
    Alarm alarm(30.0);
    Logger logger;
    sensor.subscribe(&display);
    sensor.subscribe(&alarm);

    sensor.setReading(25.0);
    sensor.setReading(31.5);
    std::printf("unsubscribe display\n");
    sensor.unsubscribe(&display);  // forgetting this leaves a dangling pointer in C++
    sensor.setReading(33.0);
    sensor.subscribe(&logger);  // new behavior added without touching Sensor
    sensor.setReading(29.5);
    std::printf("notifications sent: %d\n", sensor.notifications);
}

