import java.util.*;

public class CheckoutStrategyDemo {
    record Item(String name, double price) {}

    // The strategy interface: one method, so any lambda with this shape is a strategy
    @FunctionalInterface
    interface PricingStrategy { double apply(double subtotal); }

    // A strategy can be a full class when it has its own state...
    static class PercentOff implements PricingStrategy {
        private final double percent;
        PercentOff(double percent) { this.percent = percent; }
        public double apply(double subtotal) { return subtotal * (100 - percent) / 100; }
    }

    // The context: it uses whatever strategy it was given, with no if/switch on discount type
    static class Checkout {
        private PricingStrategy strategy;
        Checkout(PricingStrategy strategy) { this.strategy = strategy; }
        void setStrategy(PricingStrategy s) { strategy = s; }
        double total(List<Item> items) {
            double subtotal = items.stream().mapToDouble(Item::price).sum();
            return strategy.apply(subtotal);
        }
    }

    static String show(List<Item> items) {
        return String.join(", ", items.stream().map(i -> String.format("%s %.2f", i.name(), i.price())).toList());
    }

    public static void main(String[] args) {
        List<Item> cart = List.of(new Item("book", 30.00), new Item("pen", 2.50), new Item("bag", 47.50));
        System.out.println("cart: " + show(cart));

        // ...or just a lambda when it is a single rule
        Map<String, PricingStrategy> strategies = new LinkedHashMap<>();
        strategies.put("regular", subtotal -> subtotal);
        strategies.put("student", new PercentOff(10));
        strategies.put("clearance", subtotal -> subtotal >= 50 ? subtotal - 15 : subtotal);

        Checkout checkout = new Checkout(strategies.get("regular"));
        for (var entry : strategies.entrySet()) {
            checkout.setStrategy(entry.getValue()); // swap behavior at run time
            System.out.printf("%-9s -> %.2f%n", entry.getKey(), checkout.total(cart));
        }

        // Comparator is the JDK's own Strategy interface: same sort, different ordering rule
        List<Item> sorted = new ArrayList<>(cart);
        sorted.sort(Comparator.comparingDouble(Item::price));
        System.out.println("items by price: " + show(sorted));
        sorted.sort(Comparator.comparing(Item::name));
        System.out.println("items by name: " + show(sorted));
    }
}

