import java.util.*;

public class TodoMvcDemo {
    record Task(String title, boolean done) {}

    // Model: the data and its rules. It never prints and knows nothing about the view.
    static class TodoModel {
        private final List<Task> tasks = new ArrayList<>();
        private final List<Runnable> listeners = new ArrayList<>(); // Observer hook for views
        void onChange(Runnable listener) { listeners.add(listener); }
        List<Task> tasks() { return List.copyOf(tasks); }

        void add(String title) {
            if (title.isBlank()) throw new IllegalArgumentException("title must not be empty");
            tasks.add(new Task(title, false));
            listeners.forEach(Runnable::run);
        }

        void complete(int number) { // numbers shown to users start at 1
            if (number < 1 || number > tasks.size()) throw new IllegalArgumentException("no task number " + number);
            tasks.set(number - 1, new Task(tasks.get(number - 1).title(), true));
            listeners.forEach(Runnable::run);
        }
    }

    // View: only turns model data into text. Swapping it for a GUI would not touch the model.
    static class TodoView {
        void render(List<Task> tasks) {
            for (int i = 0; i < tasks.size(); i++) {
                Task t = tasks.get(i);
                System.out.println((t.done() ? "[x] " : "[ ] ") + (i + 1) + ". " + t.title());
            }
            long done = tasks.stream().filter(Task::done).count();
            System.out.println("    " + done + " of " + tasks.size() + " done");
        }
        void showError(String message) { System.out.println("error: " + message); }
    }

    // Controller: turns user input into model calls and routes errors to the view
    static class TodoController {
        private final TodoModel model;
        private final TodoView view;
        TodoController(TodoModel model, TodoView view) { this.model = model; this.view = view; }

        void handle(String line) {
            System.out.println("> " + line);
            String[] parts = line.split(" ", 2);
            String argument = parts.length > 1 ? parts[1] : "";
            try {
                switch (parts[0]) {
                    case "add" -> model.add(argument);
                    case "done" -> model.complete(Integer.parseInt(argument));
                    default -> view.showError("unknown command '" + parts[0] + "'");
                }
            } catch (IllegalArgumentException e) {
                view.showError(e.getMessage());
            }
        }
    }

    public static void main(String[] args) {
        TodoModel model = new TodoModel();
        TodoView view = new TodoView();
        model.onChange(() -> view.render(model.tasks())); // the view redraws whenever the model changes
        TodoController controller = new TodoController(model, view);

        for (String input : List.of("add Read chapter 5", "add Write lab report", "done 1", "done 7", "add", "rename 2")) {
            controller.handle(input);
        }
    }
}

