// Model: the data and its rules. It never prints and knows nothing about the view.
class TodoModel {
  #tasks = [];
  #listeners = []; // Observer hook for views
  onChange(listener) { this.#listeners.push(listener); }
  tasks() { return [...this.#tasks]; }

  add(title) {
    if (title.trim() === '') throw new Error('title must not be empty');
    this.#tasks.push({ title, done: false });
    this.#notify();
  }

  complete(number) { // numbers shown to users start at 1
    if (!(number >= 1 && number <= this.#tasks.length)) throw new Error(`no task number ${number}`);
    this.#tasks[number - 1] = { ...this.#tasks[number - 1], done: true };
    this.#notify();
  }

  #notify() { this.#listeners.forEach((listener) => listener()); }
}

// View: only turns model data into text. Swapping it for a web page would not touch the model.
class TodoView {
  render(tasks) {
    tasks.forEach((t, i) => console.log(`${t.done ? '[x]' : '[ ]'} ${i + 1}. ${t.title}`));
    console.log(`    ${tasks.filter((t) => t.done).length} of ${tasks.length} done`);
  }
  showError(message) { console.log(`error: ${message}`); }
}

// Controller: turns user input into model calls and routes errors to the view
class TodoController {
  constructor(model, view) { this.model = model; this.view = view; }

  handle(line) {
    console.log(`> ${line}`);
    const space = line.indexOf(' ');
    const command = space < 0 ? line : line.slice(0, space);
    const argument = space < 0 ? '' : line.slice(space + 1);
    try {
      if (command === 'add') this.model.add(argument);
      else if (command === 'done') this.model.complete(Number.parseInt(argument, 10));
      else this.view.showError(`unknown command '${command}'`);
    } catch (e) {
      this.view.showError(e.message);
    }
  }
}

